pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(recipient != address(0));
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory vals = new uint[](1);
        vals[0] = bound(amount, 0, type(uint256).max / 1e18);
        bool ok = c.transfer(tos, vals);
        assertTrue(ok, "transfer must return true for the authorized caller");
    }
}
